// parseRecapWindow accepts either explicit `since`/`until` ISO8601 params
// or falls back to the timeframe enum (last-month / last-3-months /
// last-6-months). Explicit dates give the CLI precise control so its
// --day / --week / --month ranges line up exactly with the server's
// aggregation boundaries.
//
// Returns a discriminated union so partial / malformed / inverted ranges
// surface as 400s instead of silently degrading to the default window —
// a CLI fat-finger on `--since` should not return 6 months of data.
type RecapWindow =
  | { ok: true; limit: number; startDate: Date; endDate: Date }
  | { ok: false; error: string }

function parseRecapWindow(c: Context<{ Bindings: Env; Variables: Variables }>): RecapWindow {
  const sinceParam = c.req.query("since")
  const untilParam = c.req.query("until")
  if (sinceParam || untilParam) {
    if (!sinceParam || !untilParam) {
      return { ok: false, error: "since and until must be provided together" }
    }
    const startDate = new Date(sinceParam)
    const endDate = new Date(untilParam)
    if (Number.isNaN(startDate.getTime()) || Number.isNaN(endDate.getTime())) {
      return { ok: false, error: "since and until must be valid ISO-8601 dates" }
    }
    if (startDate.getTime() > endDate.getTime()) {
      return { ok: false, error: "since must be on or before until" }
    }
    const limitParam = c.req.query("limit")
    const parsedLimit = limitParam ? parseInt(limitParam, 10) : 500
    const limit = Number.isNaN(parsedLimit) || parsedLimit <= 0 ? 500 : Math.min(parsedLimit, 1000)
    return { ok: true, limit, startDate, endDate }
  }
  const fallback = parseTimeframeParams(c)
  return {
    ok: true,
    limit: fallback.limit,
    startDate: fallback.startDate,
    endDate: fallback.endDate,
  }
}

