// Atomic combined write: replaces all facet rows AND updates the scalar
// aggregate columns inside a single transaction. The worker calls this
// after markComplete returns true, ensuring consumers never see a row
// whose facets and scalars disagree (e.g., fresh facets next to a stale
// 0 scalar). If either side fails the whole write rolls back, so a
// retry re-converges from a known state.
persistAnalysisAggregates(
  repoId: string,
  checkpointId: string,
