import { sql, type Kysely, type Selectable, type Transaction } from "kysely"

import type { DB, RepoCheckpointAnalyses } from "../../../db/types"
import type {
  AnalysesNamespace,
  AnalysisFacetCheckpointRef,
  AnalysisFacetCount,
  AnalysisFacetsByAgent,
  AnalysisRow,
} from "../db/db-types"
import { generateId } from "../uuid"
import { dateToStr } from "./row-helpers"

// Replace all facet rows for a checkpoint within an open transaction.
// Shared between upsertFacets (facets-only) and persistAnalysisAggregates
// (atomic facets+scalars), so both paths agree on DELETE-then-INSERT
// semantics. Caller controls the transaction boundary.
async function replaceFacetsInTransaction(
  tx: Transaction<DB>,
  repoId: string,
  checkpointId: string,
  labels: AnalysisFacetCount[],
  skills: AnalysisFacetCount[],
  toolMix: AnalysisFacetCount[],
  mcpServers: AnalysisFacetCount[],
): Promise<void> {
  for (const table of [
    "repo_checkpoint_analysis_labels",
    "repo_checkpoint_analysis_skills",
    "repo_checkpoint_analysis_tool_mix",
    "repo_checkpoint_analysis_mcp",
  ] as const) {
    await tx
      .deleteFrom(table)
      .where("repo_id", "=", repoId)
      .where("checkpoint_id", "=", checkpointId)
      .execute()
  }
  if (labels.length > 0) {
    await tx
      .insertInto("repo_checkpoint_analysis_labels")
      .values(
        labels.map((l) => ({
          repo_id: repoId,
          checkpoint_id: checkpointId,
          name: l.name,
          count: l.count,
        })),
      )
      .execute()
  }
  if (skills.length > 0) {
    await tx
      .insertInto("repo_checkpoint_analysis_skills")
      .values(
        skills.map((s) => ({
          repo_id: repoId,
          checkpoint_id: checkpointId,
          name: s.name,
          count: s.count,
        })),
      )
      .execute()
  }
  if (toolMix.length > 0) {
    await tx
      .insertInto("repo_checkpoint_analysis_tool_mix")
      .values(
        toolMix.map((t) => ({
          repo_id: repoId,
          checkpoint_id: checkpointId,
          name: t.name,
          count: t.count,
        })),
      )
      .execute()
  }
  if (mcpServers.length > 0) {
    await tx
      .insertInto("repo_checkpoint_analysis_mcp")
      .values(
        mcpServers.map((m) => ({
          repo_id: repoId,
          checkpoint_id: checkpointId,
          name: m.name,
          count: m.count,
        })),
      )
      .execute()
  }
}

