async persistAnalysisAggregates(
  repoId,
  checkpointId,
  labels,
  skills,
  toolMix,
  mcpServers,
  transcriptTokens,
  filesChanged,
) {
  // Replace facets AND set scalars in one transaction so consumers
  // never see a half-converged row. If the worker crashed between the
  // facet write and the scalar write previously, /me/recap could read
  // fresh facet aggregates next to a stale `transcript_tokens=0` and
  // silently undercount; that race is closed by the single tx here.
  await db.transaction().execute(async (tx) => {
    await replaceFacetsInTransaction(
      tx,
      repoId,
      checkpointId,
      labels,
      skills,
      toolMix,
      mcpServers,
    )
    await tx
      .updateTable("repo_checkpoint_analyses")
      .set({
        transcript_tokens: transcriptTokens,
        files_changed: filesChanged,
      })
      .where("repo_id", "=", repoId)
      .where("checkpoint_id", "=", checkpointId)
      .execute()
  })
},

