function mergeFacetsIntoAggregates(
  byAgent: Record<string, AgentAggregate>,
  facets: Map<string, AnalysisFacetsByAgent>,
): void {
  // The aggregator could in principle return any toolMix name; the response
  // shape only carries the six in TOOL_MIX_CATEGORY_KEYS, so unknown names
  // are dropped. Log when that happens so a producer/consumer drift (a new
  // category emitted by the analysis pipeline that hasn't been added to the
  // shared constant) doesn't disappear into a silent no-op.
  const validKeys = new Set<string>(TOOL_MIX_CATEGORY_KEYS)
  for (const [agent, f] of facets) {
    const agg = byAgent[agent]
    if (!agg) continue
    agg.labels = f.labels.map((l) => ({ label: l.name, count: l.count }))
    agg.skills = f.skills.map((s) => ({ skill: s.name, count: s.count }))
    agg.mcpServers = f.mcpServers.map((m) => ({ name: m.name, count: m.count }))
    agg.transcriptTokens = f.transcriptTokens
    agg.filesChanged = f.filesChanged
    for (const t of f.toolMix) {
      if (validKeys.has(t.name)) {
        ;(agg.toolMix as Record<string, number>)[t.name] = t.count
      } else {
        console.warn(
          `recap: unknown toolMix category dropped agent=${agent} name=${t.name} count=${t.count} ` +
            `— update TOOL_MIX_CATEGORY_KEYS in src/types.ts`,
        )
      }
    }
  }
}

