    : Promise.resolve([]),
])
if (myResult.status === "rejected") throw myResult.reason
const myCheckpoints = myResult.value
const teamCheckpoints = unwrapTeamSide(teamResult, "getTeamOnUserRepos", { repoParam })

// Base per-agent counts + tokens come straight off the checkpoint
