const analysisKey = (repoId: string, cpId: string) => `${repoId}:${cpId}`
const analysesById = new Map<string, import("../types").StoredCheckpointAnalysis>()
// One query per repo. Per-repo failures are isolated: a single failing
// repo (e.g. transient PlanetScale error scoped to one shard) leaves
// analyses for the other repos intact and the agent rollups for the
// failing repo's checkpoints empty. Without this isolation, the first
// throw aborted every subsequent lookup with no per-repo context in
// the resulting 500.
for (const [rid, ids] of byRepo) {
  let rows: Awaited<ReturnType<typeof db.analyses.getByCheckpointIds>>
  try {
    rows = await db.analyses.getByCheckpointIds(rid, ids)
  } catch (err) {
    recordSpanError(err)
    console.error(
      `recap: getByCheckpointIds failed repo=${rid} count=${ids.length}: ${
        err instanceof Error ? err.message : String(err)
      }`,
    )
    continue
  }
  for (const row of rows) {
    if (row.status !== "complete" || !row.analysis_json) continue
    try {
      analysesById.set(analysisKey(rid, row.checkpoint_id), JSON.parse(row.analysis_json))
    } catch (err) {
      // A `status="complete"` row with unparseable analysis_json is a real
      // anomaly — the producer wrote garbage. Surface to telemetry rather
      // than silently dropping; otherwise we'd return a perfectly-shaped
      // response with systematically understated labels/skills/toolMix
      // for the agent that owned this checkpoint.
      recordSpanError(err)
      console.error(
        `recap: malformed analysis_json repo=${rid} cp=${row.checkpoint_id}: ${
          err instanceof Error ? err.message : String(err)
        }`,
      )
    }
  }
}

