// transcriptTokens, filesChanged) for both sides. Analyses live on
// repo_checkpoint_analyses keyed by (repo_id, checkpoint_id). The two
// sides are disjoint (different checkpoint sets) so parallelize them,
// and isolate failures: me-side throws (caught by outer 500), team-side
// logs + leaves teamByAgent at the count-only state.
if (isLegacyAggregatorEnabled(c.env)) {
  const [meMerge, teamMerge] = await Promise.allSettled([
    mergeAnalysesInto(db, meByAgent, myCheckpoints),
    mergeAnalysesInto(db, teamByAgent, teamCheckpoints),
  ])
  if (meMerge.status === "rejected") throw meMerge.reason
  if (teamMerge.status === "rejected") {
    recordSpanError(teamMerge.reason)
    console.error(
      `recap: team-side mergeAnalysesInto failed repoParam=${repoParam ?? "<none>"}: ${
        teamMerge.reason instanceof Error
          ? teamMerge.reason.message
          : String(teamMerge.reason)
      }`,
    )
  }
} else {
  const [meFacets, teamFacets] = await Promise.allSettled([
    db.analyses.aggregateFacetsByAgent(
      myCheckpoints.map((cp) => ({
        repo_id: cp.repo_id,
        checkpoint_id: cp.checkpoint_id,
        agent: cp.agent,
      })),
    ),
    // teamCheckpoints is empty when repoParam is null (the upstream
    // getTeamOnUserRepos call is skipped in that case), so the
    // aggregator would just return an empty Map. Short-circuiting
    // here saves one no-op DB round trip.
    repoParam
      ? db.analyses.aggregateFacetsByAgent(
          teamCheckpoints.map((cp) => ({
            repo_id: cp.repo_id,
            checkpoint_id: cp.checkpoint_id,
            agent: cp.agent,
          })),
        )
      : Promise.resolve(new Map<string, AnalysisFacetsByAgent>()),
  ])
  if (meFacets.status === "rejected") throw meFacets.reason
  const teamFacetsValue = unwrapTeamSettled(
    teamFacets,
    "aggregateFacetsByAgent",
    { repoParam },
    () => new Map<string, AnalysisFacetsByAgent>(),
  )
  mergeFacetsIntoAggregates(meByAgent, meFacets.value)
  mergeFacetsIntoAggregates(teamByAgent, teamFacetsValue)
}

