// MySQL error codes reference (mysql/include/mysqld_error.h):
//   1061  ER_DUP_KEYNAME — `CREATE INDEX <name>` where `<name>` already exists
//   1050  ER_TABLE_EXISTS_ERROR — defensive cover for engines that surface
//                                 the table-level "exists" instead
// Matching by code is robust to error-message rewording across driver
// versions, MySQL versions, and locale settings — text matching is not.
const ER_DUP_KEYNAME = 1061
const ER_TABLE_EXISTS_ERROR = 1050

interface MysqlError {
  errno?: number
  code?: string
}

function isAlreadyExistsError(error: unknown): boolean {
  if (typeof error !== "object" || error === null) return false
  const e = error as MysqlError
  return (
    e.errno === ER_DUP_KEYNAME ||
    e.errno === ER_TABLE_EXISTS_ERROR ||
    e.code === "ER_DUP_KEYNAME" ||
    e.code === "ER_TABLE_EXISTS_ERROR"
  )
}

async function createIndexIfNotExists(
  db: Kysely<unknown>,
  indexName: string,
  table: string,
  columns: string[],
) {
  try {
    await db.schema.createIndex(indexName).on(table).columns(columns).execute()
  } catch (error: unknown) {
    if (isAlreadyExistsError(error)) return
    throw error
  }
}

