// extractFacetsFromAnalysis derives the four facet arrays + two scalars
// the SQL aggregator reads at recap time. Pulled out of the loop body
// so unit tests can pin the count/filter semantics without spinning up
// a database.
export function extractFacetsFromAnalysis(analysis: AnalysisJsonShape): {
  labels: Array<{ name: string; count: number }>
  skills: Array<{ name: string; count: number }>
  toolMix: Array<{ name: string; count: number }>
  mcpServers: Array<{ name: string; count: number }>
  transcriptTokens: number
  filesChanged: number
} {
  return {
    labels: countOccurrences(analysis.extraction?.labels ?? []),
    skills: countOccurrences(analysis.skillsUsed ?? []),
    toolMix: extractToolMix(analysis),
    // mcpServersUsed in the analysis JSON is already {name, count}-shaped
    // (extractToolMetrics in analysis-queue.ts produces it that way).
    // Filter zero/negative counts so the backfill never plants dead rows.
    mcpServers: (analysis.mcpServersUsed ?? [])
      .filter((m) => (m.count ?? 0) > 0)
      .map((m) => ({ name: m.name, count: m.count ?? 0 })),
    transcriptTokens: analysis.total_transcript_tokens ?? 0,
    filesChanged: analysis.totalFilesChanged ?? 0,
  }
}

