          row.checkpoint_id,
          facets.labels,
          facets.skills,
          facets.toolMix,
          facets.mcpServers,
          facets.transcriptTokens,
          facets.filesChanged,
        )
      }
      // Drives the `processed < max` loop guard regardless of dry-run vs
      // write — without this, --dry-run silently ignored --limit because
      // only `wouldUpsert` was incremented in the dry-run branch.
      processed++
    }

    cursor = {
      repo_id: batch[batch.length - 1]!.repo_id,
      checkpoint_id: batch[batch.length - 1]!.checkpoint_id,
    }
    if (dryRun) {
      console.log(
        `would-upsert=${wouldUpsert} skipped=${skipped} cursor=${cursor.repo_id}/${cursor.checkpoint_id}`,
      )
    } else {
      console.log(
        `processed=${processed} skipped=${skipped} cursor=${cursor.repo_id}/${cursor.checkpoint_id}`,
      )
    }
  }

  return { processed, skipped, wouldUpsert }
}

async function main(): Promise<void> {
  const db = createDb()
  const analyses = createAnalysesNamespace(db)

  const limitFlag = process.argv.find((a) => a.startsWith("--limit="))?.split("=")[1]
  const max = limitFlag ? parseInt(limitFlag, 10) : Infinity
  const dryRun = process.argv.includes("--dry-run")

  const { processed, skipped, wouldUpsert } = await runBackfill({ db, analyses }, { max, dryRun })

  // High skip ratios (>1%) signal something other than an isolated row
  // with bad JSON — a producer schema regression or a systemic problem
  // worth alerting on. Exit non-zero so an operator notices instead of
  // assuming a clean run.
  const skipRatio = processed > 0 ? skipped / processed : 0
  if (dryRun) {
    console.log(`done (dry-run). would_upsert=${wouldUpsert} skipped=${skipped}`)
  } else {
    console.log(`done. processed=${processed} skipped=${skipped}`)
  }
  await db.destroy()
  if (processed > 0 && skipRatio > SKIP_RATIO_THRESHOLD) {
    console.error(
      `backfill: skip ratio ${(skipRatio * 100).toFixed(2)}% exceeds ${
        SKIP_RATIO_THRESHOLD * 100
      }% threshold (skipped=${skipped} of ${processed}). ` +
        `Investigate before treating run as complete.`,
    )
    process.exit(1)
  }
}

