import type { Kysely } from "kysely"
import { describe, expect, it, vi } from "vitest"

import type { DB } from "../db/types"
import type { AnalysesNamespace } from "../src/lib/db/db-types"
import {
  countOccurrences,
  extractFacetsFromAnalysis,
  extractToolMix,
  runBackfill,
} from "./backfill-analysis-facets"

// Build a fake Kysely DB whose select chain ends with `.execute()` returning
// the supplied batches in order. The backfill script only uses selectFrom +
// select + where + orderBy + limit + execute, so we don't need a full Kysely.
function makeMockDb(batches: Array<Array<{
  repo_id: string
  checkpoint_id: string
  analysis_json: string
}>>): { db: Kysely<DB>; executeMock: ReturnType<typeof vi.fn> } {
  const executeMock = vi.fn()
  for (const batch of batches) executeMock.mockResolvedValueOnce(batch)
  // Backfill keeps paging until execute() returns an empty array.
  executeMock.mockResolvedValue([])

  const chain = {
    selectFrom: vi.fn().mockReturnThis(),
    select: vi.fn().mockReturnThis(),
    where: vi.fn().mockReturnThis(),
    orderBy: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    execute: executeMock,
  }
  return { db: chain as unknown as Kysely<DB>, executeMock }
}

function makeAnalysesStub(): {
  analyses: Pick<AnalysesNamespace, "persistAnalysisAggregates">
  persist: ReturnType<typeof vi.fn>
} {
  const persist = vi.fn().mockResolvedValue(undefined)
  return {
    analyses: {
      persistAnalysisAggregates: persist as unknown as AnalysesNamespace["persistAnalysisAggregates"],
    },
    persist,
  }
}

const FULL_ANALYSIS_JSON = JSON.stringify({
  extraction: { labels: ["bug_fix", "bug_fix", "refactor"] },
  skillsUsed: ["debugging"],
  mcpServersUsed: [
    { name: "github", count: 3 },
    { name: "linear", count: 0 }, // filtered out
  ],
  toolProfile: {
    categories: {
      shell: { count: 5 },
      fileOps: { count: 10 },
      search: { count: 0 },
      mcp: { count: 3 },
      agent: { count: 0 },
      other: { count: 2 },
    },
  },
  total_transcript_tokens: 1234,
  totalFilesChanged: 7,
})

describe("countOccurrences", () => {
  it("collapses duplicates into name+count rows", () => {
    expect(countOccurrences(["a", "a", "b"])).toEqual([
      { name: "a", count: 2 },
      { name: "b", count: 1 },
    ])
  })

  it("returns an empty array for empty input", () => {
    expect(countOccurrences([])).toEqual([])
  })
})

describe("extractToolMix", () => {
  it("filters out zero-count categories", () => {
    const out = extractToolMix({
      toolProfile: {
        categories: {
          shell: { count: 5 },
          fileOps: { count: 0 },
          other: null,
        },
      },
    })
    expect(out).toEqual([{ name: "shell", count: 5 }])
  })

  it("returns [] when toolProfile is missing", () => {
    expect(extractToolMix({})).toEqual([])
  })
})

describe("extractFacetsFromAnalysis", () => {
  it("derives all four facet arrays + scalars from a fully-shaped analysis", () => {
    const facets = extractFacetsFromAnalysis(JSON.parse(FULL_ANALYSIS_JSON))
    expect(facets.labels).toEqual(
      expect.arrayContaining([
        { name: "bug_fix", count: 2 },
        { name: "refactor", count: 1 },
      ]),
    )
    expect(facets.skills).toEqual([{ name: "debugging", count: 1 }])
    // mcpServers with count=0 is dropped.
    expect(facets.mcpServers).toEqual([{ name: "github", count: 3 }])
    // toolMix excludes zero-count categories (search, agent).
    expect(facets.toolMix.map((t) => t.name).sort()).toEqual(
      ["fileOps", "mcp", "other", "shell"].sort(),
    )
    expect(facets.transcriptTokens).toBe(1234)
    expect(facets.filesChanged).toBe(7)
  })

  it("defaults missing scalars to 0 (legacy-row backfill case)", () => {
    const facets = extractFacetsFromAnalysis({})
    expect(facets.transcriptTokens).toBe(0)
    expect(facets.filesChanged).toBe(0)
    expect(facets.labels).toEqual([])
  })
})

describe("runBackfill", () => {
  it("processes every row and writes via persistAnalysisAggregates by default", async () => {
    const { db } = makeMockDb([
      [
        { repo_id: "repo-A", checkpoint_id: "cp-1", analysis_json: FULL_ANALYSIS_JSON },
        { repo_id: "repo-A", checkpoint_id: "cp-2", analysis_json: FULL_ANALYSIS_JSON },
      ],
    ])
    const { analyses, persist } = makeAnalysesStub()

    const result = await runBackfill({ db, analyses }, { max: Infinity, dryRun: false })

    expect(result).toEqual({ processed: 2, skipped: 0, wouldUpsert: 0 })
    expect(persist).toHaveBeenCalledTimes(2)
    // Single combined call — facets and scalars share one transaction so
    // the worker and backfill never disagree on torn-write semantics.
    const firstCall = persist.mock.calls[0]
    expect(firstCall?.[0]).toBe("repo-A")
    expect(firstCall?.[1]).toBe("cp-1")
  })

  it("dry-run never calls persistAnalysisAggregates and counts wouldUpsert", async () => {
    const { db } = makeMockDb([
      [
        { repo_id: "repo-A", checkpoint_id: "cp-1", analysis_json: FULL_ANALYSIS_JSON },
        { repo_id: "repo-A", checkpoint_id: "cp-2", analysis_json: FULL_ANALYSIS_JSON },
      ],
    ])
    const { analyses, persist } = makeAnalysesStub()

    const result = await runBackfill({ db, analyses }, { max: Infinity, dryRun: true })

    expect(result.wouldUpsert).toBe(2)
    expect(result.processed).toBe(2)
    expect(persist).not.toHaveBeenCalled()
  })

  it("honours --limit under dry-run (regression: previously processed never advanced)", async () => {
    // Three rows in one batch; limit caps at 2. Without the fix, the loop
    // would run forever in dry-run because `processed` only advanced in
    // the write branch.
    const { db } = makeMockDb([
      [
        { repo_id: "repo-A", checkpoint_id: "cp-1", analysis_json: FULL_ANALYSIS_JSON },
        { repo_id: "repo-A", checkpoint_id: "cp-2", analysis_json: FULL_ANALYSIS_JSON },
        { repo_id: "repo-A", checkpoint_id: "cp-3", analysis_json: FULL_ANALYSIS_JSON },
      ],
    ])
    const { analyses } = makeAnalysesStub()

    const result = await runBackfill({ db, analyses }, { max: 2, dryRun: true })

    // The inner loop processes the whole batch before the outer guard
    // re-evaluates; we just need to confirm we don't infinite-loop and
    // that wouldUpsert tracks each row in the batch.
    expect(result.wouldUpsert).toBeGreaterThanOrEqual(2)
    expect(result.processed).toBeGreaterThanOrEqual(2)
  })

  it("skips rows with malformed JSON without throwing, but lets non-JSON errors propagate", async () => {
    const { db } = makeMockDb([
      [
        { repo_id: "repo-A", checkpoint_id: "cp-bad", analysis_json: "{not valid json" },
        { repo_id: "repo-A", checkpoint_id: "cp-ok", analysis_json: FULL_ANALYSIS_JSON },
      ],
    ])
    const { analyses, persist } = makeAnalysesStub()
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {})

    const result = await runBackfill({ db, analyses }, { max: Infinity, dryRun: false })

    expect(result.skipped).toBe(1)
    expect(result.processed).toBe(2) // includes both the skipped and the OK row
    expect(persist).toHaveBeenCalledTimes(1) // only cp-ok actually persisted
    warnSpy.mockRestore()
  })

  it("propagates infrastructure errors instead of swallowing them as parse failures", async () => {
    const { db } = makeMockDb([
      [{ repo_id: "repo-A", checkpoint_id: "cp-1", analysis_json: FULL_ANALYSIS_JSON }],
    ])
    const { analyses } = makeAnalysesStub()
    // persistAnalysisAggregates throws a non-SyntaxError; it MUST bubble up.
    ;(analyses.persistAnalysisAggregates as ReturnType<typeof vi.fn>).mockRejectedValueOnce(
      new Error("planetscale connection lost"),
    )

    await expect(
      runBackfill({ db, analyses }, { max: Infinity, dryRun: false }),
    ).rejects.toThrow(/planetscale connection lost/)
  })
})

