```ts
classifyTool(call: ToolCall): ToolMixCategory {
  const name = call.name
  if (
    name === "exec_command" ||
    name === "local_shell_call" ||
    name === "write_stdin" ||
    name === "bash" ||
    name === "shell"
  ) {
    return "shell"
  }
  if (
    name === "apply_patch" ||
    name === "read_file" ||
    name === "write_file" ||
    name === "edit"
  ) {
    return "fileOps"
  }
  if (name === "update_plan") return "agent"
  // Codex MCP-tool naming convention: leading underscore (e.g.
  // `_list_pull_request_review_threads`, `_fetch_pr_comments`). The parser
  // doesn't currently extract a server name from these — `extractMcpServerFromTool`
  // returns null below — but the bucket is correct.
  if (name.startsWith("_")) return "mcp"
  if (name === "grep" || name === "glob" || name === "search") return "search"
  return "other"
}

extractSkillFromTool(_call: ToolCall): string | null {
  // Codex has no equivalent of Claude's `Skill` tool today.
  return null
}

extractMcpServerFromTool(_call: ToolCall): string | null {
  // Codex transcripts contain `mcp_tool_call_end` payloads, but the
  // current parser doesn't surface a server name in `toolCalls[]`.
  // Returning null preserves recap correctness; surfacing server names
  // is a follow-up parser change.
  return null
}
```

