  const checkpointsNs = createCheckpointsNamespace(kysely)
  const reposNs = createReposNamespace(kysely)
  const db = { checkpoints: checkpointsNs, repos: reposNs } as Pick<Db, "checkpoints" | "repos">

  const loadTranscript: BackfillDeps["loadTranscript"] = async ({
    repoId,
    checkpointId,
  }) => {
