// inside the class:
classifyTool(call: ToolCall): ToolMixCategoryKey {
  const name = call.name
  if (
    name === "exec_command" ||
    name === "local_shell_call" ||
    name === "write_stdin" ||
    name === "bash" ||
    name === "shell"
  ) {
    return "shell"
  }
  if (
    name === "apply_patch" ||
    name === "read_file" ||
    name === "write_file" ||
    name === "edit"
  ) {
    return "fileOps"
  }
  if (name === "update_plan") return "agent"
